    "CREATE TABLE customer_leads (\n\tid INTEGER NOT NULL, \n\tlead_no VARCHAR(32) NOT NULL, \n\tcustomer_id INTEGER NOT NULL, \n\trequest_type VARCHAR(32) NOT NULL, \n\tbudget NUMERIC(18, 2), \n\ttarget TEXT NOT NULL, \n\tstatus VARCHAR(16) NOT NULL, \n\towner_id INTEGER, \n\tconverted_order_id INTEGER, \n\tclosed_reason TEXT, \n\tnote TEXT, \n\tcreated_by VARCHAR(64) NOT NULL, \n\tupdated_by VARCHAR(64) NOT NULL, \n\tcreated_at DATETIME DEFAULT (CURRENT_TIMESTAMP) NOT NULL, \n\tupdated_at DATETIME DEFAULT (CURRENT_TIMESTAMP) NOT NULL, \n\tCONSTRAINT pk_customer_leads PRIMARY KEY (id), \n\tCONSTRAINT ck_customer_leads_lead_type_valid CHECK (request_type IN ('FIND_ACCOUNT', 'SELL_ACCOUNT', 'SPECIFIC_SEARCH')), \n\tCONSTRAINT ck_customer_leads_lead_status_valid CHECK (status IN ('OPEN', 'CONVERTED', 'CLOSED')), \n\tCONSTRAINT ck_customer_leads_lead_budget_nonneg CHECK (budget IS NULL OR budget >= 0), \n\tCONSTRAINT fk_customer_leads_converted_order_id FOREIGN KEY(converted_order_id) REFERENCES orders (id) ON DELETE SET NULL, \n\tCONSTRAINT fk_customer_leads_customer_id FOREIGN KEY(customer_id) REFERENCES customers (id) ON DELETE RESTRICT, \n\tCONSTRAINT fk_customer_leads_owner_id FOREIGN KEY(owner_id) REFERENCES users (id) ON DELETE SET NULL, \n\tCONSTRAINT uq_customer_leads_no UNIQUE (lead_no)\n)",
    "CREATE TABLE deposits (\n\tid INTEGER NOT NULL, \n\tpool_id INTEGER NOT NULL, \n\tcounterparty_id INTEGER, \n\tsource_order_id INTEGER, \n\tpaid_amount NUMERIC(18, 2) NOT NULL, \n\treturned_amount NUMERIC(18, 2) NOT NULL, \n\tlost_amount NUMERIC(18, 2) DEFAULT '0' NOT NULL, \n\tstatus VARCHAR(24) NOT NULL, \n\tpaid_on DATE NOT NULL, \n\texpected_release_on DATE, \n\treleased_on DATE, \n\tlost_on DATE, \n\tnote TEXT, \n\tcreated_by VARCHAR(64) NOT NULL, \n\tupdated_by VARCHAR(64) NOT NULL, \n\tcreated_at DATETIME DEFAULT (CURRENT_TIMESTAMP) NOT NULL, \n\tupdated_at DATETIME DEFAULT (CURRENT_TIMESTAMP) NOT NULL, \n\tCONSTRAINT pk_deposits PRIMARY KEY (id), \n\tCONSTRAINT ck_deposits_deposit_status_valid CHECK (status IN ('PAID', 'PARTIALLY_RETURNED', 'RETURNED', 'LOST', 'CANCELLED')), \n\tCONSTRAINT ck_deposits_amount_nonneg CHECK (paid_amount >= 0 AND returned_amount >= 0 AND lost_amount >= 0), \n\tCONSTRAINT ck_deposits_released_amount_within_paid CHECK (returned_amount + lost_amount <= paid_amount), \n\tCONSTRAINT fk_deposits_counterparty_id FOREIGN KEY(counterparty_id) REFERENCES counterparties (id) ON DELETE SET NULL, \n\tCONSTRAINT fk_deposits_pool_id FOREIGN KEY(pool_id) REFERENCES pools (id) ON DELETE RESTRICT, \n\tCONSTRAINT fk_deposits_source_order_id FOREIGN KEY(source_order_id) REFERENCES orders (id) ON DELETE SET NULL\n)",
    "CREATE TABLE import_rows (\n\tid INTEGER NOT NULL, \n\tbatch_id INTEGER NOT NULL, \n\trow_no INTEGER NOT NULL, \n\traw JSON NOT NULL, \n\tmapped_order_id INTEGER, \n\tmapped_account_id INTEGER, \n\tmapped_by VARCHAR(64), \n\tmapped_at DATETIME, \n\tmapping_basis TEXT, \n\tmapped_before JSON, \n\tstatus VARCHAR(16) NOT NULL, \n\tunlinked_transfer BOOLEAN NOT NULL, \n\tissue_note TEXT, \n\tcreated_at DATETIME DEFAULT (CURRENT_TIMESTAMP) NOT NULL, \n\tupdated_at DATETIME DEFAULT (CURRENT_TIMESTAMP) NOT NULL, \n\tCONSTRAINT pk_import_rows PRIMARY KEY (id), \n\tCONSTRAINT ck_import_rows_import_row_status_valid CHECK (status IN ('PENDING', 'MAPPED', 'UNMAPPED', 'IMPORTED', 'SKIPPED', 'ROLLED_BACK')), \n\tCONSTRAINT ck_import_rows_row_no_positive CHECK (row_no > 0), \n\tCONSTRAINT fk_import_rows_batch_id FOREIGN KEY(batch_id) REFERENCES import_batches (id) ON DELETE CASCADE, \n\tCONSTRAINT fk_import_rows_mapped_account_id FOREIGN KEY(mapped_account_id) REFERENCES accounts (id) ON DELETE SET NULL, \n\tCONSTRAINT fk_import_rows_mapped_order_id FOREIGN KEY(mapped_order_id) REFERENCES orders (id) ON DELETE SET NULL, \n\tCONSTRAINT uq_import_rows_batch_row UNIQUE (batch_id, row_no)\n)",
    "CREATE TABLE installments (\n\tid INTEGER NOT NULL, \n\tinst_no VARCHAR(32) NOT NULL, \n\torder_id INTEGER NOT NULL, \n\tcontract_type VARCHAR(24) NOT NULL, \n\tpolicy_version_id INTEGER, \n\tpolicy_snapshot JSON, \n\tprincipal NUMERIC(18, 2) NOT NULL, \n\tdown_payment NUMERIC(18, 2) NOT NULL, \n\tservice_fee NUMERIC(18, 2) DEFAULT '0' NOT NULL, \n\tperiods INTEGER NOT NULL, \n\tper_period_service_fee NUMERIC(18, 2) DEFAULT '0' NOT NULL, \n\tper_period NUMERIC(18, 2) NOT NULL, \n\tpaid_amount NUMERIC(18, 2) NOT NULL, \n\twaived_amount NUMERIC(18, 2) DEFAULT '0' NOT NULL, \n\tbad_debt_amount NUMERIC(18, 2) DEFAULT '0' NOT NULL, \n\tfinal_period_adjustment NUMERIC(18, 2) DEFAULT '0' NOT NULL, \n\tstatus VARCHAR(16) NOT NULL, \n\tdelivery_mode VARCHAR(24), \n\tdelivered_on DATE, \n\tfirst_due_on DATE, \n\tnote TEXT, \n\tcreated_by VARCHAR(64) NOT NULL, \n\tupdated_by VARCHAR(64) NOT NULL, \n\tcreated_at DATETIME DEFAULT (CURRENT_TIMESTAMP) NOT NULL, \n\tupdated_at DATETIME DEFAULT (CURRENT_TIMESTAMP) NOT NULL, form_extra JSON, \n\tCONSTRAINT pk_installments PRIMARY KEY (id), \n\tCONSTRAINT ck_installments_installment_contract_valid CHECK (contract_type IN ('STOCK_SALE', 'ADVANCE_PURCHASE', 'PICKUP_SALE', 'CONSIGNMENT_SALE')), \n\tCONSTRAINT ck_installments_installment_delivery_mode_valid CHECK (delivery_mode IS NULL OR delivery_mode IN ('PLATFORM_OPERATOR', 'CUSTOMER_SELF')), \n\tCONSTRAINT ck_installments_installment_status_valid CHECK (status IN ('PENDING', 'ACTIVE', 'OVERDUE', 'SETTLED', 'DELIVERED', 'DEFAULTED', 'CLOSED', 'CANCELLED')), \n\tCONSTRAINT ck_installments_down_payment_lte_principal CHECK (down_payment <= principal), \n\tCONSTRAINT ck_installments_periods_positive CHECK (periods > 0), \n\tCONSTRAINT ck_installments_principal_lte_schedule_total CHECK (principal <= down_payment + per_period * periods), \n\tCONSTRAINT ck_installments_amount_nonneg CHECK (principal >= 0 AND down_payment >= 0 AND service_fee >= 0 AND per_period_service_fee >= 0 AND per_period >= 0 AND paid_amount >= 0 AND waived_amount >= 0 AND bad_debt_amount >= 0), \n\tCONSTRAINT fk_installments_order_id FOREIGN KEY(order_id) REFERENCES orders (id) ON DELETE RESTRICT, \n\tCONSTRAINT fk_installments_policy_version_id FOREIGN KEY(policy_version_id) REFERENCES policy_versions (id) ON DELETE SET NULL, \n\tCONSTRAINT uq_installments_no UNIQUE (inst_no), \n\tCONSTRAINT uq_installments_order UNIQUE (order_id)\n)",
    "CREATE TABLE order_counterparty_roles (\n\tid INTEGER NOT NULL, \n\torder_id INTEGER NOT NULL, \n\tcounterparty_id INTEGER NOT NULL, \n\trole VARCHAR(32) NOT NULL, \n\tcreated_at DATETIME DEFAULT (CURRENT_TIMESTAMP) NOT NULL, \n\tupdated_at DATETIME DEFAULT (CURRENT_TIMESTAMP) NOT NULL, \n\tCONSTRAINT pk_order_counterparty_roles PRIMARY KEY (id), \n\tCONSTRAINT ck_order_counterparty_roles_counterparty_role_valid CHECK (role IN ('PEER', 'SUPPLIER', 'PLATFORM')), \n\tCONSTRAINT fk_order_counterparty_roles_counterparty_id FOREIGN KEY(counterparty_id) REFERENCES counterparties (id) ON DELETE RESTRICT, \n\tCONSTRAINT fk_order_counterparty_roles_order_id FOREIGN KEY(order_id) REFERENCES orders (id) ON DELETE CASCADE, \n\tCONSTRAINT uq_order_counterparty_role UNIQUE (order_id, counterparty_id, role)\n)",
    "CREATE TABLE order_customer_roles (\n\tid INTEGER NOT NULL, \n\torder_id INTEGER NOT NULL, \n\tcustomer_id INTEGER NOT NULL, \n\trole VARCHAR(32) NOT NULL, \n\tcreated_at DATETIME DEFAULT (CURRENT_TIMESTAMP) NOT NULL, \n\tupdated_at DATETIME DEFAULT (CURRENT_TIMESTAMP) NOT NULL, \n\tCONSTRAINT pk_order_customer_roles PRIMARY KEY (id), \n\tCONSTRAINT ck_order_customer_roles_customer_role_valid CHECK (role IN ('SELLER', 'BUYER', 'CONSIGNOR', 'INSTALLMENT_CUSTOMER')), \n\tCONSTRAINT fk_order_customer_roles_customer_id FOREIGN KEY(customer_id) REFERENCES customers (id) ON DELETE RESTRICT, \n\tCONSTRAINT fk_order_customer_roles_order_id FOREIGN KEY(order_id) REFERENCES orders (id) ON DELETE CASCADE, \n\tCONSTRAINT uq_order_customer_role UNIQUE (order_id, customer_id, role)\n)",
    "CREATE TABLE order_events (\n\tid INTEGER NOT NULL, \n\tevent_no VARCHAR(32) NOT NULL, \n\torder_id INTEGER NOT NULL, \n\tevent_type VARCHAR(16) NOT NULL, \n\tamount NUMERIC(18, 2) NOT NULL, \n\tportion VARCHAR(16) NOT NULL, \n\toccurred_on DATE NOT NULL, \n\tpool_id INTEGER, \n\toffset_event_id INTEGER, \n\tdelivery_mode VARCHAR(24), \n\tis_posted BOOLEAN NOT NULL, \n\tposted_at DATETIME, \n\treason TEXT, \n\trefund_responsibility VARCHAR(32), \n\toperator_user_ids JSON, \n\tnote TEXT, \n\tcreated_by VARCHAR(64) NOT NULL, \n\tupdated_by VARCHAR(64) NOT NULL, \n\tcreated_at DATETIME DEFAULT (CURRENT_TIMESTAMP) NOT NULL, \n\tupdated_at DATETIME DEFAULT (CURRENT_TIMESTAMP) NOT NULL, form_extra JSON, \n\tCONSTRAINT pk_order_events PRIMARY KEY (id), \n\tCONSTRAINT ck_order_events_event_delivery_mode_valid CHECK (delivery_mode IS NULL OR delivery_mode IN ('PLATFORM_OPERATOR', 'CUSTOMER_SELF')), \n\tCONSTRAINT ck_order_events_event_type_valid CHECK (event_type IN ('BUY', 'COST', 'SELL', 'PAYMENT', 'DELIVER', 'CANCEL', 'REFUND')), \n\tCONSTRAINT ck_order_events_portion_valid CHECK (portion IN ('PRINCIPAL', 'PROFIT', 'GROSS')), \n\tCONSTRAINT ck_order_events_amount_nonneg CHECK (amount >= 0), \n\tCONSTRAINT fk_order_events_offset_event_id FOREIGN KEY(offset_event_id) REFERENCES order_events (id) ON DELETE SET NULL, \n\tCONSTRAINT fk_order_events_order_id FOREIGN KEY(order_id) REFERENCES orders (id) ON DELETE RESTRICT, \n\tCONSTRAINT fk_order_events_pool_id FOREIGN KEY(pool_id) REFERENCES pools (id) ON DELETE RESTRICT, \n\tCONSTRAINT uq_order_events_no UNIQUE (event_no)\n)",
    "CREATE TABLE order_links (\n\tid INTEGER NOT NULL, \n\tsource_order_id INTEGER NOT NULL, \n\ttarget_order_id INTEGER NOT NULL, \n\trelation_type VARCHAR(16) NOT NULL, \n\tsplit_ratio NUMERIC(18, 2), \n\tsplit_amount NUMERIC(18, 2), \n\tnote TEXT, \n\tcreated_by VARCHAR(64) NOT NULL, \n\tupdated_by VARCHAR(64) NOT NULL, \n\tcreated_at DATETIME DEFAULT (CURRENT_TIMESTAMP) NOT NULL, \n\tupdated_at DATETIME DEFAULT (CURRENT_TIMESTAMP) NOT NULL, form_extra JSON, \n\tCONSTRAINT pk_order_links PRIMARY KEY (id), \n\tCONSTRAINT ck_order_links_order_link_type_valid CHECK (relation_type IN ('SOURCE', 'FOLLOW_UP')), \n\tCONSTRAINT ck_order_links_order_link_not_self CHECK (source_order_id <> target_order_id), \n\tCONSTRAINT ck_order_links_order_link_amount_valid CHECK (split_amount IS NULL OR split_amount > 0), \n\tCONSTRAINT ck_order_links_order_link_ratio_valid CHECK (split_ratio IS NULL OR (split_ratio > 0 AND split_ratio <= 100)), \n\tCONSTRAINT fk_order_links_source_order_id FOREIGN KEY(source_order_id) REFERENCES orders (id) ON DELETE RESTRICT, \n\tCONSTRAINT fk_order_links_target_order_id FOREIGN KEY(target_order_id) REFERENCES orders (id) ON DELETE RESTRICT, \n\tCONSTRAINT uq_order_links_pair UNIQUE (source_order_id, target_order_id)\n)",
    "CREATE TABLE order_profit_allocations (\n\tid INTEGER NOT NULL, \n\torder_id INTEGER NOT NULL, \n\tallocation_type VARCHAR(16), \n\tuser_id INTEGER, \n\trole VARCHAR(32) NOT NULL, \n\tallocation_rate NUMERIC(18, 2) NOT NULL, \n\tpolicy_version_id INTEGER, \n\tcreated_at DATETIME DEFAULT (CURRENT_TIMESTAMP) NOT NULL, \n\tupdated_at DATETIME DEFAULT (CURRENT_TIMESTAMP) NOT NULL, allocation_amount NUMERIC(18, 2) DEFAULT '0' NOT NULL, \n\tCONSTRAINT pk_order_profit_allocations PRIMARY KEY (id), \n\tCONSTRAINT ck_order_profit_allocations_allocation_role_valid CHECK (role IN ('OWNER', 'BUYER', 'SALES', 'SERVICE')), \n\tCONSTRAINT ck_order_profit_allocations_rate_max CHECK (allocation_rate <= 100), \n\tCONSTRAINT ck_order_profit_allocations_rate_nonneg CHECK (allocation_rate >= 0), \n\tCONSTRAINT fk_order_profit_allocations_order_id FOREIGN KEY(order_id) REFERENCES orders (id) ON DELETE CASCADE, \n\tCONSTRAINT fk_order_profit_allocations_policy_version_id FOREIGN KEY(policy_version_id) REFERENCES policy_versions (id) ON DELETE SET NULL, \n\tCONSTRAINT fk_order_profit_allocations_user_id FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE SET NULL, \n\tCONSTRAINT uq_order_profit_alloc UNIQUE (order_id, allocation_type, user_id, role)\n)",
    "CREATE TABLE rebate_records (\n\tid INTEGER NOT NULL, \n\trebate_no VARCHAR(32) NOT NULL, \n\tsource_order_id INTEGER NOT NULL, \n\trebate_type VARCHAR(16) NOT NULL, \n\tchannel VARCHAR(64), \n\trate NUMERIC(18, 2) NOT NULL, \n\tbase_amount NUMERIC(18, 2) NOT NULL, \n\tpolicy_version_id INTEGER, \n\tpolicy_snapshot JSON, \n\tlink_status VARCHAR(24) NOT NULL, \n\tstatus VARCHAR(24) NOT NULL, \n\tcollected_on DATE NOT NULL, \n\texpected_on DATE, \n\tnote TEXT, \n\tcreated_by VARCHAR(64) NOT NULL, \n\tupdated_by VARCHAR(64) NOT NULL, \n\tcreated_at DATETIME DEFAULT (CURRENT_TIMESTAMP) NOT NULL, \n\tupdated_at DATETIME DEFAULT (CURRENT_TIMESTAMP) NOT NULL, \n\tCONSTRAINT pk_rebate_records PRIMARY KEY (id), \n\tCONSTRAINT ck_rebate_records_rebate_link_status_valid CHECK (link_status IN ('LINKED', 'UNLINKED', 'ORPHAN', 'UNLINKED_TRANSFER')), \n\tCONSTRAINT ck_rebate_records_rebate_type_valid CHECK (rebate_type IN ('BUY', 'SELL')), \n\tCONSTRAINT ck_rebate_records_rebate_status_valid CHECK (status IN ('OPEN', 'PARTIALLY_SETTLED', 'SETTLED', 'VOID')), \n\tCONSTRAINT ck_rebate_records_rate_max CHECK (rate <= 100), \n\tCONSTRAINT ck_rebate_records_amount_nonneg CHECK (rate >= 0 AND base_amount >= 0), \n\tCONSTRAINT fk_rebate_records_policy_version_id FOREIGN KEY(policy_version_id) REFERENCES policy_versions (id) ON DELETE SET NULL, \n\tCONSTRAINT fk_rebate_records_source_order_id FOREIGN KEY(source_order_id) REFERENCES orders (id) ON DELETE RESTRICT, \n\tCONSTRAINT uq_rebate_records_no UNIQUE (rebate_no)\n)",
    "CREATE TABLE \"cashflow\" (\n\tid INTEGER NOT NULL, \n\tflow_no VARCHAR(32) NOT NULL, \n\tpool_id INTEGER NOT NULL, \n\toccurred_on DATE NOT NULL, \n\tnature VARCHAR(16) NOT NULL, \n\tfund_nature VARCHAR(16) DEFAULT 'BUSINESS' NOT NULL, \n\taccounting_attribute VARCHAR(32) DEFAULT 'OPERATING_EXPENSE' NOT NULL, \n\tcategory VARCHAR(32) NOT NULL, \n\tdirection VARCHAR(8) NOT NULL, \n\tamount NUMERIC(18, 2) NOT NULL, \n\tstatus VARCHAR(16) DEFAULT 'APPROVED' NOT NULL, \n\torder_id INTEGER, \n\tdeposit_id INTEGER, \n\torder_event_id INTEGER, \n\ttransfer_id VARCHAR(64), \n\treversal_of_id INTEGER, \n\treviewed_by VARCHAR(64), \n\treviewed_at DATETIME, \n\treversal_reason TEXT, \n\tnote TEXT, \n\tcreated_by VARCHAR(64) NOT NULL, \n\tupdated_by VARCHAR(64) NOT NULL, \n\tcreated_at DATETIME DEFAULT (CURRENT_TIMESTAMP) NOT NULL, \n\tupdated_at DATETIME DEFAULT (CURRENT_TIMESTAMP) NOT NULL, form_extra JSON, \n\tCONSTRAINT pk_cashflow PRIMARY KEY (id), \n\tCONSTRAINT fk_cashflow_order_id FOREIGN KEY(order_id) REFERENCES orders (id) ON DELETE SET NULL, \n\tCONSTRAINT ck_cashflow_amount_nonneg CHECK (amount >= 0), \n\tCONSTRAINT ck_cashflow_cashflow_direction_nature_valid CHECK ((nature = 'INTERNAL' AND transfer_id IS NOT NULL) OR (direction = 'IN' AND nature IN ('EXTERNAL_IN', 'BUSINESS_IN')) OR (direction = 'OUT' AND nature = 'BUSINESS_OUT') OR (category = 'CANCEL' AND nature = 'BUSINESS_IN' AND direction IN ('IN', 'OUT'))), \n\tCONSTRAINT ck_cashflow_cashflow_fund_nature_valid CHECK (fund_nature IN ('BUSINESS', 'EXTERNAL', 'INTERNAL')), \n\tCONSTRAINT ck_cashflow_cashflow_status_valid CHECK (status IN ('PENDING', 'APPROVED', 'REJECTED')), \n\tCONSTRAINT ck_cashflow_cashflow_accounting_attribute_valid CHECK (accounting_attribute IN ('SELF_REVENUE', 'SELF_DIRECT_COST', 'TH_DIRECT_COST', 'TH_REVENUE', 'DFQ_PRINCIPAL', 'SERVICE_REVENUE', 'REBATE_INCOME', 'OPERATING_EXPENSE', 'DEPOSIT', 'EXTERNAL_FUNDING', 'INTERNAL_TRANSFER', 'REVERSAL', 'REFUND')), \n\tCONSTRAINT uq_cashflow_no UNIQUE (flow_no), \n\tCONSTRAINT ck_cashflow_cashflow_nature_valid CHECK (nature IN ('EXTERNAL_IN', 'BUSINESS_IN', 'BUSINESS_OUT', 'INTERNAL')), \n\tCONSTRAINT ck_cashflow_cashflow_direction_valid CHECK (direction IN ('IN', 'OUT')), \n\tCONSTRAINT fk_cashflow_deposit_id FOREIGN KEY(deposit_id) REFERENCES deposits (id) ON DELETE SET NULL, \n\tCONSTRAINT fk_cashflow_pool_id FOREIGN KEY(pool_id) REFERENCES pools (id) ON DELETE RESTRICT, \n\tCONSTRAINT fk_cashflow_reversal_of_id FOREIGN KEY(reversal_of_id) REFERENCES cashflow (id) ON DELETE RESTRICT, \n\tCONSTRAINT ck_cashflow_internal_transfer_link_valid CHECK (nature != 'INTERNAL' OR transfer_id IS NOT NULL), \n\tCONSTRAINT uq_cashflow_event UNIQUE (order_event_id), \n\tCONSTRAINT uq_cashflow_reversal UNIQUE (reversal_of_id), \n\tCONSTRAINT fk_cashflow_order_event_id FOREIGN KEY(order_event_id) REFERENCES order_events (id) ON DELETE SET NULL\n)",
    "CREATE TABLE installment_dispositions (\n\tid INTEGER NOT NULL, \n\tinstallment_id INTEGER NOT NULL, \n\taccount_id INTEGER NOT NULL, \n\taction VARCHAR(16) NOT NULL, \n\toccurred_on DATE NOT NULL, \n\trelated_order_id INTEGER, \n\tnote TEXT NOT NULL, \n\tcreated_by VARCHAR(64) NOT NULL, \n\tupdated_by VARCHAR(64) NOT NULL, \n\tcreated_at DATETIME DEFAULT (CURRENT_TIMESTAMP) NOT NULL, \n\tupdated_at DATETIME DEFAULT (CURRENT_TIMESTAMP) NOT NULL, \n\tCONSTRAINT pk_installment_dispositions PRIMARY KEY (id), \n\tCONSTRAINT ck_installment_dispositions_installment_disposition_action_valid CHECK (action IN ('RECOVER', 'RESELL')), \n\tCONSTRAINT fk_installment_dispositions_account_id FOREIGN KEY(account_id) REFERENCES accounts (id) ON DELETE RESTRICT, \n\tCONSTRAINT fk_installment_dispositions_installment_id FOREIGN KEY(installment_id) REFERENCES installments (id) ON DELETE RESTRICT, \n\tCONSTRAINT fk_installment_dispositions_related_order_id FOREIGN KEY(related_order_id) REFERENCES orders (id) ON DELETE RESTRICT, \n\tCONSTRAINT uq_installment_disposition_action UNIQUE (installment_id, action)\n)",
    "CREATE TABLE installment_schedules (\n\tid INTEGER NOT NULL, \n\tinstallment_id INTEGER NOT NULL, \n\tperiod_no INTEGER NOT NULL, \n\tdue_on DATE NOT NULL, \n\tservice_fee_rate NUMERIC(18, 2) DEFAULT '0' NOT NULL, \n\tdue_amount NUMERIC(18, 2) NOT NULL, \n\treceived_amount NUMERIC(18, 2) NOT NULL, \n\twaived_amount NUMERIC(18, 2) DEFAULT '0' NOT NULL, \n\treceived_on DATE, \n\tstatus VARCHAR(16) NOT NULL, \n\tcreated_at DATETIME DEFAULT (CURRENT_TIMESTAMP) NOT NULL, \n\tupdated_at DATETIME DEFAULT (CURRENT_TIMESTAMP) NOT NULL, \n\tCONSTRAINT pk_installment_schedules PRIMARY KEY (id), \n\tCONSTRAINT ck_installment_schedules_schedule_status_valid CHECK (status IN ('PENDING', 'PARTIAL', 'PAID', 'OVERDUE', 'WAIVED')), \n\tCONSTRAINT ck_installment_schedules_amount_nonneg CHECK (due_amount >= 0 AND received_amount >= 0 AND waived_amount >= 0), \n\tCONSTRAINT ck_installment_schedules_period_no_nonnegative CHECK (period_no >= 0), \n\tCONSTRAINT ck_installment_schedules_settled_amount_within_due CHECK (received_amount + waived_amount <= due_amount), \n\tCONSTRAINT fk_installment_schedules_installment_id FOREIGN KEY(installment_id) REFERENCES installments (id) ON DELETE CASCADE, \n\tCONSTRAINT uq_installment_period UNIQUE (installment_id, period_no)\n)",
    "CREATE TABLE rebate_settlements (\n\tid INTEGER NOT NULL, \n\tsettlement_no VARCHAR(48) NOT NULL, \n\trebate_record_id INTEGER NOT NULL, \n\tsettled_on DATE NOT NULL, \n\tgross_amount NUMERIC(18, 2) NOT NULL, \n\tplatform_fee NUMERIC(18, 2) NOT NULL, \n\tnet_amount NUMERIC(18, 2) NOT NULL, \n\tcashflow_id INTEGER, \n\tfee_cashflow_id INTEGER, \n\treversal_of_id INTEGER, \n\tnote TEXT, \n\tcreated_by VARCHAR(64) NOT NULL, \n\tupdated_by VARCHAR(64) NOT NULL, \n\tcreated_at DATETIME DEFAULT (CURRENT_TIMESTAMP) NOT NULL, \n\tupdated_at DATETIME DEFAULT (CURRENT_TIMESTAMP) NOT NULL, \n\tCONSTRAINT pk_rebate_settlements PRIMARY KEY (id), \n\tCONSTRAINT ck_rebate_settlements_amount_nonneg CHECK (gross_amount >= 0 AND platform_fee >= 0 AND net_amount >= 0), \n\tCONSTRAINT ck_rebate_settlements_net_amount_matches_breakdown CHECK (net_amount = gross_amount - platform_fee), \n\tCONSTRAINT fk_rebate_settlements_cashflow_id FOREIGN KEY(cashflow_id) REFERENCES cashflow (id) ON DELETE SET NULL, \n\tCONSTRAINT fk_rebate_settlements_fee_cashflow_id FOREIGN KEY(fee_cashflow_id) REFERENCES cashflow (id) ON DELETE SET NULL, \n\tCONSTRAINT fk_rebate_settlements_rebate_record_id FOREIGN KEY(rebate_record_id) REFERENCES rebate_records (id) ON DELETE RESTRICT, \n\tCONSTRAINT fk_rebate_settlements_reversal_of_id FOREIGN KEY(reversal_of_id) REFERENCES rebate_settlements (id) ON DELETE RESTRICT, \n\tCONSTRAINT uq_rebate_settlements_flow UNIQUE (cashflow_id), \n\tCONSTRAINT uq_rebate_settlements_no UNIQUE (settlement_no)\n)",
